// Shared column definitions, so every table has the same id and timestamp conventions.
// Server-only. Imported with relative paths because drizzle-kit and tsx run outside Nuxt and
// do not know the `#layers` alias.
import { sql } from 'drizzle-orm'
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core'

// uuid primary key, generated by Postgres. Clients treat ids as opaque.
export const id = () => uuid('id').primaryKey().default(sql`gen_random_uuid()`)

export const createdAt = () => timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow()

// `$onUpdate` runs in the app on every update made through Drizzle; the database has no trigger for it.
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date())

// Fractional ordering key (see the `fractional-indexing` package): a string that sorts between its neighbours.
// It must compare byte by byte, but the database default collation (en_US.utf8) does not. Pinning the
// column to COLLATE "C" makes `ORDER BY` and indexes agree with the library.
export const orderKey = customType<{ data: string; driverData: string }>({
  dataType: () => 'text COLLATE "C"',
})

// CHECK constraint "column is one of these values". Text plus CHECK rather than a Postgres enum:
// adding a value later is an ordinary migration. The values are written into the SQL as literals,
// because DDL cannot take query parameters; only pass constants from code.
export const oneOf = (column: unknown, values: readonly string[]) =>
  sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(', '))})`
